enum AdrStatus { PROPOSED, ACCEPTED, REJECTED, SUPERSEDED }

record Adr(
    int number,
    String title,
    AdrStatus status,
    String context,
    String decision,
    String consequences,
    String date
) {}

class AdrLog {
    private final Map<Integer, Adr> records = new LinkedHashMap<>();

    void add(Adr adr) { records.put(adr.number(), adr); }

    void markSuperseded(int oldNumber, int newNumber) {
        Adr old = records.get(oldNumber);
        Adr updated = new Adr(
            old.number(), old.title(), AdrStatus.SUPERSEDED,
            old.context(), old.decision(),
            old.consequences() + " [Zastapione przez ADR-" + newNumber + "]",
            old.date()
        );
        records.put(oldNumber, updated); // stary wpis zostaje, tylko zmienia status
    }
}

// ZLE: nadpisanie tresci ADR-0001 zamiast napisania nowego, zastepujacego wpisu
void updateDecisionWrong(AdrLog log) {
    Adr old = log.get(1);
    Adr overwritten = new Adr(
        old.number(), old.title(), AdrStatus.ACCEPTED,
        "Uzywamy PostgreSQL", // <- podmieniono tresc, jakby MongoDB nigdy nie bylo wybrane
        "Zdecydowano o PostgreSQL", "Brak problemow z joinami", old.date()
    );
    log.add(overwritten); // historia "dlaczego wybralismy MongoDB" zniknela bezpowrotnie
}

// DOBRZE: nowy ADR zastepuje stary, historia zostaje kompletna
void supersedeDecisionRight(AdrLog log) {
    Adr newDecision = new Adr(
        2, "Uzyj PostgreSQL zamiast MongoDB do przechowywania zamowien",
        AdrStatus.ACCEPTED,
        "Zapytania analityczne wymagaja zlaczen, ktorych MongoDB nie obsluguje wygodnie",
        "Migrujemy przechowywanie zamowien na PostgreSQL",
        "Wymaga migracji danych; zyskujemy pelne wsparcie dla zlaczen SQL",
        "2026-03-15"
    );
    log.add(newDecision);
    log.markSuperseded(1, 2); // ADR-0001 zostaje w rejestrze, ze statusem SUPERSEDED
}
